// Package charnames is the Unicode character name table the launcher
// searches: every character the Unicode Character Database names, with
// its aliases, generated by internal/tools/unicodegen and embedded
// compressed. In memory it stays in its encoded form, each name a few
// varint word ids into one word list, and a search walks it without
// allocating.
package charnames

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"math/bits"
	"slices"
	"strings"
	"sync"
	"unicode/utf8"

	"github.com/stubbedev/lys-lib/intconv"

	"github.com/stubbedev/lys-shell/service/launcher"
)

// Magic starts the encoded table.
const Magic = "lys-charnames/2\n"

// The encoding's codes: a name is a sequence of word codes, each a varint
// word id from FirstWord on (a word is one or more words of the name, so
// common phrases cost one code), or HexTail for "-" and the character's own
// code point in hex, which ends algorithmic names such as CJK
// COMPATIBILITY IDEOGRAPH-F900. An entry's head byte holds its name's code
// count (at most MaxNameCodes), its Kind shifted by 4, and the HasAliases
// and HasGap flags.
const (
	HexTail      = 0
	FirstWord    = 1
	MaxNameCodes = 15
	HasAliases   = 1 << 6
	HasGap       = 1 << 7
)

// Kind is how a character shows on its own.
type Kind uint8

// The kinds.
const (
	// KindGraphic shows as itself.
	KindGraphic Kind = iota
	// KindCombining marks the character before it.
	KindCombining
	// KindControl is invisible: a control, format or separator character.
	KindControl
)

//go:embed names.bin.gz
var embedded []byte

// Table is the decoded name table.
type Table struct {
	data    []byte
	nWords  uint32
	words   []uint32
	entries int
	count   int
}

var (
	sharedOnce  sync.Once
	sharedTable *Table
	sharedErr   error
)

// Shared is the embedded table, decompressed on first use and kept.
func Shared() (*Table, error) {
	sharedOnce.Do(func() {
		zr, err := gzip.NewReader(bytes.NewReader(embedded))
		if err != nil {
			sharedErr = fmt.Errorf("character names: %w", err)
			return
		}
		data, err := io.ReadAll(zr)
		if err != nil {
			sharedErr = fmt.Errorf("character names: %w", err)
			return
		}
		sharedTable, sharedErr = Parse(slices.Clip(data))
	})
	return sharedTable, sharedErr
}

// Len is how many characters the table names.
func (t *Table) Len() int { return t.count }

// Parse checks an encoded table end to end and indexes its words.
func Parse(data []byte) (*Table, error) {
	rest, ok := bytes.CutPrefix(data, []byte(Magic))
	if !ok {
		return nil, errors.New("character names: bad magic")
	}
	r := reader{data: data, at: len(data) - len(rest)}
	nWords, ok := r.uvarint()
	if !ok || nWords >= 1<<20 {
		return nil, errors.New("character names: bad word count")
	}
	t := &Table{data: data, nWords: uint32(nWords), words: make([]uint32, 0, (nWords+wordStride-1)/wordStride)}
	for i := range t.nWords {
		if i%wordStride == 0 {
			t.words = append(t.words, uint32(r.at)) //nolint:gosec // the table is far below 4 GiB
		}
		n, ok := r.byte()
		if !ok || n == 0 || !r.skip(int(n)) {
			return nil, fmt.Errorf("character names: word %d is cut short", i)
		}
	}
	count, ok := r.uvarint()
	if !ok || count > utf8.MaxRune {
		return nil, errors.New("character names: bad entry count")
	}
	t.entries, t.count = r.at, int(count)
	cp := rune(-1)
	for i := range t.count {
		e, ok := t.entry(&r, cp)
		if !ok {
			return nil, fmt.Errorf("character names: entry %d is malformed", i)
		}
		cp = e.cp
	}
	if r.at != len(data) {
		return nil, errors.New("character names: trailing bytes")
	}
	return t, nil
}

type reader struct {
	data []byte
	at   int
}

func (r *reader) byte() (byte, bool) {
	if r.at >= len(r.data) {
		return 0, false
	}
	b := r.data[r.at]
	r.at++
	return b, true
}

func (r *reader) uvarint() (uint64, bool) {
	v, n := binary.Uvarint(r.data[r.at:])
	if n <= 0 {
		return 0, false
	}
	r.at += n
	return v, true
}

func (r *reader) skip(n int) bool {
	if r.at+n > len(r.data) {
		return false
	}
	r.at += n
	return true
}

type entry struct {
	cp         rune
	kind       Kind
	nameCodes  int
	aliasCodes int
	codes      int
}

func (t *Table) entry(r *reader, prev rune) (entry, bool) {
	head, ok := r.byte()
	if !ok {
		return entry{}, false
	}
	e := entry{cp: prev + 1, kind: Kind(head >> 4 & 3), nameCodes: int(head & MaxNameCodes)}
	if head&HasGap != 0 {
		gap, ok := r.uvarint()
		if !ok || gap > utf8.MaxRune {
			return entry{}, false
		}
		e.cp += rune(gap)
	}
	if head&HasAliases != 0 {
		n, ok := r.byte()
		if !ok {
			return entry{}, false
		}
		e.aliasCodes = int(n)
	}
	if e.nameCodes == 0 || e.kind > KindControl || e.cp > utf8.MaxRune {
		return entry{}, false
	}
	e.codes = r.at
	for range e.nameCodes + e.aliasCodes {
		code, ok := r.uvarint()
		if !ok || code-FirstWord >= uint64(t.nWords) && code != HexTail {
			return entry{}, false
		}
	}
	return e, true
}

const wordStride = 8

func (t *Table) word(code uint64) []byte {
	id := code - FirstWord
	at := t.words[id/wordStride]
	for range id % wordStride {
		at += 1 + uint32(t.data[at])
	}
	n := uint32(t.data[at])
	return t.data[at+1 : at+1+n]
}

// Char is one named character found.
type Char struct {
	Rune   rune
	Kind   Kind
	Score  int32
	at     int
	length int
}

// appendTitle appends word, lower case but for the first letter of each of
// its words.
func appendTitle[T byte | rune](dst []T, word []byte) []T {
	start := true
	for _, b := range word {
		if !start && b >= 'A' && b <= 'Z' {
			b += 'a' - 'A'
		}
		start = b == ' ' || b == '-'
		dst = append(dst, T(b))
	}
	return dst
}

func appendHexTail[T byte | rune](dst []T, cp rune) []T {
	const digits = "0123456789ABCDEF"
	dst = append(dst, '-')
	width := 4
	for cp>>(4*width) != 0 {
		width++
	}
	for i := width - 1; i >= 0; i-- {
		dst = append(dst, T(digits[cp>>(4*i)&15]))
	}
	return dst
}

func appendCodes[T byte | rune](t *Table, dst []T, cp rune, at, n int) []T {
	r := reader{data: t.data, at: at}
	for i := range n {
		code, _ := r.uvarint()
		if code == HexTail {
			dst = appendHexTail(dst, cp)
			continue
		}
		if i > 0 {
			dst = append(dst, ' ')
		}
		dst = appendTitle(dst, t.word(code))
	}
	return dst
}

// AppendName appends c's name in title case ("Rightwards Arrow").
func (t *Table) AppendName(dst []byte, c Char) []byte {
	r := reader{data: t.data, at: c.at}
	e, _ := t.entry(&r, c.Rune-1)
	return appendCodes(t, dst, c.Rune, e.codes, e.nameCodes)
}

// Glyph is how c shows on its own: itself, a combining mark on a dotted
// circle, a C0 control as its control picture, "" for the invisible rest.
func (c Char) Glyph() string {
	switch {
	case c.Kind == KindCombining:
		return "◌" + string(c.Rune)
	case c.Kind == KindGraphic:
		return string(c.Rune)
	case c.Rune < 0x20:
		return string(0x2400 + c.Rune)
	case c.Rune == 0x7f:
		return "␡"
	}
	return ""
}

const (
	maxTokens      = 6
	maxTokenLen    = 32
	aliasPenalty   = 24
	wholeWordBonus = 24
	commonBonus    = 16
	literalScore   = 1 << 10
)

// Searcher finds characters by name. It reuses its memory across
// searches, so a search allocates nothing once warm; it belongs to one
// goroutine.
type Searcher struct {
	t      *Table
	tokens [maxTokens][maxTokenLen]byte
	lens   [maxTokens]int
	n      int
	prefix [maxTokens][]uint64
	exact  [maxTokens][]uint64
	hay    []rune
	top    []Char
}

// NewSearcher searches t.
func (t *Table) NewSearcher() *Searcher { return &Searcher{t: t} }

// Search is the limit best characters for query, best first: each of its
// words starts a word of the name or of an alias, and the fuzzy score of
// the name (or, found only by an alias, of the name and aliases, for less)
// ranks them. An empty query lists the first characters. "U+2192" and a
// character typed as itself find that character. The result is valid until
// the next Search.
func (s *Searcher) Search(q *launcher.FuzzyQuery, query string, limit int) []Char {
	s.top = s.top[:0]
	if limit <= 0 {
		return s.top
	}
	query = strings.TrimSpace(query)
	if cp, ok := literal(query); ok {
		return s.exactly(cp)
	}
	if !s.tokenize(query) {
		return s.top
	}
	s.markWords()
	r := reader{data: s.t.data, at: s.t.entries}
	cp := rune(-1)
	for range s.t.count {
		at := r.at
		e, _ := s.t.entry(&r, cp)
		cp = e.cp
		c := Char{Rune: e.cp, Kind: e.kind, at: at}
		if s.n == 0 {
			s.keep(c, limit)
			if len(s.top) == limit {
				break
			}
			continue
		}
		inName, ok, exact := s.matchesWords(e)
		if !ok {
			continue
		}
		if c.Score, c.length, ok = s.score(q, e, inName, exact); ok {
			s.keep(c, limit)
		}
	}
	return s.top
}

func literal(query string) (rune, bool) {
	if len(query) >= 6 && len(query) <= 8 && (query[0] == 'U' || query[0] == 'u') && query[1] == '+' {
		var cp rune
		for i := 2; i < len(query); i++ {
			c := query[i]
			switch {
			case c >= '0' && c <= '9':
				cp = cp<<4 | rune(c-'0')
			case c >= 'A' && c <= 'F':
				cp = cp<<4 | rune(c-'A'+10)
			case c >= 'a' && c <= 'f':
				cp = cp<<4 | rune(c-'a'+10)
			default:
				return 0, false
			}
		}
		return cp, true
	}
	r, size := utf8.DecodeRuneInString(query)
	if size == len(query) && r >= 0x80 && r != utf8.RuneError {
		return r, true
	}
	return 0, false
}

func (s *Searcher) exactly(cp rune) []Char {
	r := reader{data: s.t.data, at: s.t.entries}
	prev := rune(-1)
	for range s.t.count {
		at := r.at
		e, _ := s.t.entry(&r, prev)
		prev = e.cp
		if e.cp > cp {
			break
		}
		if e.cp == cp {
			s.top = append(s.top, Char{Rune: cp, Kind: e.kind, Score: literalScore, at: at})
			break
		}
	}
	return s.top
}

func (s *Searcher) tokenize(query string) bool {
	s.n = 0
	i := 0
	for i < len(query) {
		for i < len(query) && (query[i] == ' ' || query[i] == '-') {
			i++
		}
		start := i
		for i < len(query) && query[i] != ' ' && query[i] != '-' {
			i++
		}
		if start == i {
			continue
		}
		if s.n == maxTokens || i-start > maxTokenLen {
			return false
		}
		for j := start; j < i; j++ {
			b := query[j]
			if b >= 0x80 {
				return false
			}
			if b >= 'a' && b <= 'z' {
				b -= 'a' - 'A'
			}
			s.tokens[s.n][j-start] = b
		}
		s.lens[s.n] = i - start
		s.n++
	}
	return true
}

// wordMatch is how token sits in phrase: starting one of its words, or
// being one of them.
func wordMatch(phrase, token []byte) (prefix, exact bool) {
	for i := 0; i+len(token) <= len(phrase); i++ {
		if (i == 0 || phrase[i-1] == ' ' || phrase[i-1] == '-') && bytes.Equal(phrase[i:i+len(token)], token) {
			prefix = true
			end := i + len(token)
			if end == len(phrase) || phrase[end] == ' ' || phrase[end] == '-' {
				return true, true
			}
		}
	}
	return prefix, false
}

func (s *Searcher) markWords() {
	size := int(s.t.nWords+63) / 64
	for k := range s.n {
		for _, set := range []*[]uint64{&s.prefix[k], &s.exact[k]} {
			if cap(*set) < size {
				*set = make([]uint64, size)
			}
			*set = (*set)[:size]
			clear(*set)
		}
	}
	at := s.t.words[0]
	for id := range s.t.nWords {
		n := uint32(s.t.data[at])
		phrase := s.t.data[at+1 : at+1+n]
		at += 1 + n
		for k := range s.n {
			prefix, exact := wordMatch(phrase, s.tokens[k][:s.lens[k]])
			if prefix {
				s.prefix[k][id>>6] |= 1 << (id & 63)
			}
			if exact {
				s.exact[k][id>>6] |= 1 << (id & 63)
			}
		}
	}
}

// matchesWords reports every token starting a word of e's name and
// aliases, whether the name alone has them all, and how many are whole
// words.
func (s *Searcher) matchesWords(e entry) (inName, ok bool, exact int) {
	var seen, seenName, whole uint8
	r := reader{data: s.t.data, at: e.codes}
	for i := range e.nameCodes + e.aliasCodes {
		code, _ := r.uvarint()
		if code == HexTail {
			continue
		}
		id := code - FirstWord
		for k := range s.n {
			if s.prefix[k][id>>6]&(1<<(id&63)) == 0 {
				continue
			}
			seen |= 1 << k
			if i < e.nameCodes {
				seenName |= 1 << k
			}
			if s.exact[k][id>>6]&(1<<(id&63)) != 0 {
				whole |= 1 << k
			}
		}
	}
	all := uint8(1)<<s.n - 1
	return seenName == all, seen == all, bits.OnesCount8(whole)
}

func (s *Searcher) score(q *launcher.FuzzyQuery, e entry, inName bool, exact int) (int32, int, bool) {
	s.hay = appendCodes(s.t, s.hay[:0], e.cp, e.codes, e.nameCodes)
	length := len(s.hay)
	if !inName {
		s.hay = append(s.hay, ' ')
		s.hay = appendCodes(s.t, s.hay, e.cp, s.aliasStart(e), e.aliasCodes)
	}
	score, ok := q.Score(s.hay)
	if !ok {
		return 0, 0, false
	}
	score += exact * wholeWordBonus
	if common(e.cp) {
		score += commonBonus
	}
	if !inName {
		score = max(score-aliasPenalty, 1)
	}
	return intconv.Clamp[int32](min(score, literalScore-1)), length, true
}

// common reports a character from the blocks a launcher search is usually
// after: Latin-1 and IPA, then punctuation, currency signs, arrows, maths,
// box drawing and the other symbols up to U+2BFF.
func common(r rune) bool { return r < 0x300 || r >= 0x2000 && r < 0x2c00 }

func (s *Searcher) aliasStart(e entry) int {
	r := reader{data: s.t.data, at: e.codes}
	for range e.nameCodes {
		r.uvarint()
	}
	return r.at
}

func better(a, b Char) int {
	if a.Score != b.Score {
		return int(b.Score - a.Score)
	}
	if a.length != b.length {
		return a.length - b.length
	}
	return int(a.Rune - b.Rune)
}

func (s *Searcher) keep(c Char, limit int) {
	if len(s.top) == limit && better(c, s.top[len(s.top)-1]) >= 0 {
		return
	}
	at, _ := slices.BinarySearchFunc(s.top, c, better)
	if len(s.top) == limit {
		copy(s.top[at+1:], s.top[at:])
		s.top[at] = c
		return
	}
	s.top = slices.Insert(s.top, at, c)
}
